import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.Ce1WstT_.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/system-design.md","filePath":"system-design/system-design.md"}'),n={name:"system-design/system-design.md"};function r(o,e,l,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[a('<div class="page-header"><span class="category-badge">SYSTEM DESIGN</span><h1>System Overview</h1><p class="page-subtitle">A monolithic backend scaling strategy utilizing decoupled frontend architecture and ACID transactions.</p><hr class="header-divider"></div><p>The system follows a three-tier decoupled client-server architecture designed for high maintainability, stateless backend scaling, and clear separation of concerns.</p><h2 id="_1-presentation-tier-frontend" tabindex="-1">1. Presentation Tier (Frontend) <a class="header-anchor" href="#_1-presentation-tier-frontend" aria-label="Permalink to &quot;1. Presentation Tier (Frontend)&quot;">​</a></h2><ul><li><strong>Framework</strong>: React 18 (Single Page Application) using Vite and TypeScript.</li><li><strong>Responsibilities</strong>: UI rendering, client-side route protection, form capture with validation, and server state synchronization.</li><li><strong>Location</strong>: <code>client/</code> directory.</li></ul><h2 id="_2-application-tier-backend-rest-api" tabindex="-1">2. Application Tier (Backend REST API) <a class="header-anchor" href="#_2-application-tier-backend-rest-api" aria-label="Permalink to &quot;2. Application Tier (Backend REST API)&quot;">​</a></h2><ul><li><strong>Framework</strong>: Node.js and Express.js using TypeScript.</li><li><strong>Responsibilities</strong>: HTTP request routing, JWT validation, Zod payload validation, business logic, transaction management, and RBAC enforcement.</li><li><strong>Location</strong>: <code>server/</code> directory.</li></ul><h2 id="_3-persistence-tier-database" tabindex="-1">3. Persistence Tier (Database) <a class="header-anchor" href="#_3-persistence-tier-database" aria-label="Permalink to &quot;3. Persistence Tier (Database)&quot;">​</a></h2><ul><li><strong>Engine</strong>: PostgreSQL 16 on Supabase.</li><li><strong>Responsibilities</strong>: Relational data persistence, foreign key enforcement, row-level pessimistic locking, and ACID transaction isolation.</li><li><strong>Driver</strong>: Node.js <code>pg</code> library.</li></ul><div class="info custom-block"><p class="custom-block-title">ARCHITECTURE NOTE</p><p>This is a <strong>monolithic backend application</strong> with a <strong>separately deployed frontend</strong>. It is <strong>NOT</strong> a microservices architecture.</p></div>',9)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
